text={}
def e(k,t,tag='p',cls=''):
 text[k]=t;return f'<{tag} data-edit="{k}" class="{cls}">{t}</{tag}>'
def meta(k,t):return e(k+'-meta',t,'p','meta')
def foot(k,n):return '<footer>'+e('disclaimer','虚构计划／暂无实测结果','span')+e(k+'-page',n,'span')+'</footer>'
def fig(k):return f'<svg class="plane plane-{k}" data-plane="{k}" viewBox="0 0 '+('1000 650' if k=='a' else '1440 360')+'" role="img" aria-label="原创平面空间示意，非地点或记录"></svg>'
def cap(k):return e(k+'-caption','原创平面空间示意，非地点或记录。','p','caption')
