body='<nav>'+''.join(f'<a href="#{k}" data-page="{k}">{i:02} {n}</a>' for i,(k,n) in enumerate([('enter','进入'),('stay','停留'),('read','读清'),('leave','离开')],1))+'</nav><div class="status">沉浸空间 · 平面知觉候选｜原效果评价：差／适配二级｜空间感为待判断的视觉关系，不是用户实验结果</div><main>'
body+='<section class="page page-a" id="enter">'+meta('a','平面空间／计划草案')+'<div class="opening"><div class="opening-copy">'+e('title','重新看见','h1')+e('title-second','岸线','h1')+e('lead','先停在一个画面前。深浅可以有不同读法，计划里的未知需要写清楚。')+'</div><div class="opening-figure">'+fig('a')+cap('a')+'</div></div>'+foot('a','01')+'</section>'
